const $=s=>document.querySelector(s);
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let entries=[],entry=null,currentId='',matched=false,miss='',result={title:'Ready',reason:'Prepare an input, then run the checker.',metrics:'No request submitted.'},mode='answers',records=[],sessionRecords=[];
const manifests=new Map();
async function api(path,body){const r=await fetch('/v0/'+path,body===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});return {ok:r.ok,status:r.status,data:await r.json()};}
function fail(e){setResult('Connection error','The API could not load. Check the connection and reload.',e.message);}
function setResult(title,reason,metrics=''){result={title,reason,metrics};renderResult();}
function renderResult(){const cls=result.title.toLowerCase();$('#readout').className='readout '+(cls==='accept'?'accept':['reject','no checker','no match','input error'].includes(cls)?'reject':'');$('#verdict').textContent=result.title;$('#reason').textContent=result.reason;$('#metrics').textContent=result.metrics;}
async function getEntry(id){if(manifests.has(id))return manifests.get(id);const r=await api('catalog/'+encodeURIComponent(id));if(r.ok){manifests.set(id,r.data);return r.data;}return null;}
async function select(id){currentId=id;entry=await getEntry(id);matched=false;miss='';setResult('Ready','Prepare an input, then run the checker.','No request submitted for this entry.');document.querySelectorAll('.selector').forEach(b=>b.setAttribute('aria-pressed',b.dataset.id===id));$('#input').value=JSON.stringify(entry?.check?.example_input||{},null,2);$('#input-note').textContent=entry?.check?'Edit the input before checking it.':'No runnable checker. Run check returns HTTP 409.';$('#package-id').textContent=id;renderEntry();draw();}
function hashValue(hash,label){return `<details class="hash"><summary>SHA-256 <code>${esc(hash.slice(0,8))}…${esc(hash.slice(-8))}</code></summary><input readonly aria-label="Full SHA-256 for ${esc(label)}" value="${esc(hash)}"></details>`;}
function renderEntry(){const e=entry,summary=entries.find(x=>x.id===currentId);$('#replay-status').textContent=e?.replay.status==='real'?'Real replay':summary?.replay_status==='recorded'?'Recorded / not re-run':'';if(!e){$('#entry').innerHTML=`<h3>${esc(summary?.title||currentId)}</h3><p class="notice">Recorded stub. Not re-run by fvapi. The full manifest is unavailable in this mock.</p><p>${esc(summary?.claim||'Select another entry to inspect its evidence.')}</p>`;return;}
$('#entry').innerHTML=`<h3>${esc(e.title)}</h3><p>${esc(e.claim)}</p>${e.replay.status==='recorded'?'<p class="notice"><strong>Recorded stub. Not re-run by fvapi.</strong> This transcript comes from an earlier run.</p>':'<p class="muted">Re-run the delivered bundle to establish the result yourself. A checker verdict does not replace proof replay.</p>'}<div class="evidence-grid"><div><h3>Statements to verify</h3>${e.statements.map(s=>`<p class="muted">${esc(s.name)}<br>${esc(s.file)}:${s.line}</p><pre>${esc(s.text)}</pre>`).join('')}<h3>Delivered files and SHA-256</h3><p class="muted">${e.closure.length} files. Expand a directory to inspect its files. Open a hash to select its full value.</p>${groups().map(([dir,files])=>`<details class="closure-group"><summary>${esc(dir)} <span>${files.length} file${files.length===1?'':'s'}</span></summary>${files.map(f=>`<div class="closure-file"><code class="file-path" title="${esc(f.path)}">${esc(f.path)}</code><div class="file-meta"><span>${f.bytes} bytes</span>${hashValue(f.sha256,f.path)}</div></div>`).join('')}</details>`).join('')}</div><div><h3>Replay on your machine</h3><pre>${esc(e.replay.command)}</pre><button id="copy">Copy replay command</button> <a href="/v0/bundles/${encodeURIComponent(e.id)}.tar.gz">Download bundle</a><p class="muted">${esc(e.replay.note)}</p><dl><dt>Expected axioms</dt><dd>${esc(e.replay.expect_axioms.join(', ')||'None')}</dd><dt>Toolchain</dt><dd>${esc(e.toolchain)}</dd><dt>Required libraries</dt><dd>${e.requires.map(esc).join('<br>')||'None'}</dd><dt>Licence</dt><dd>${esc(e.licence.spdx)}</dd><dt>Third-party notices</dt><dd>${e.licence.third_party.map(t=>`${esc(t.name)} / ${esc(t.spdx)}<br>${esc(t.source)}`).join('<br>')||'No third-party notices in this manifest.'}</dd><dt>Source</dt><dd>${esc(e.source.repo)}<br>Commit ${esc(e.source.commit)}<br>${e.source.paths.map(esc).join('<br>')}</dd></dl>${e.subject.artifact?`<h3>Subject artifact</h3><p class="muted"><code class="file-path" title="${esc(e.subject.artifact.name)}">${esc(e.subject.artifact.name)}</code>${e.subject.artifact.bytes} bytes</p>${hashValue(e.subject.artifact.sha256,e.subject.artifact.name)}`:''}${e.replay.transcript?`<details><summary>Recorded transcript</summary><pre>${esc(e.replay.transcript)}</pre></details>`:''}</div></div>`;
$('#copy').onclick=async()=>{try{await navigator.clipboard.writeText(e.replay.command);$('#copy').textContent='Command copied';}catch{$('#copy').textContent='Select and copy the command above';}};}
function groups(){const grouped=new Map();for(const f of entry?.closure||[]){const bits=f.path.split('/');const dir=bits.length===1?'Bundle root':bits.slice(0,Math.min(2,bits.length-1)).join('/');if(!grouped.has(dir))grouped.set(dir,[]);grouped.get(dir).push(f);}return [...grouped];}
function node(id,x,y,w,label,sub,cls='',click=false){const short=(s,n)=>s.length>n?s.slice(0,n-1)+'…':s;return `<g class="node ${cls}"${click?` role="button" tabindex="0" data-node="${esc(id)}" aria-label="${esc(label+', '+sub)}"`:''}><title>${esc(label+' / '+sub)}</title><rect x="${x}" y="${y}" width="${w}" height="56" rx="2"/><text x="${x+11}" y="${y+23}">${esc(short(label,Math.floor(w/(matchMedia('(max-width:800px)').matches?9:7))))}</text><text class="sub" x="${x+11}" y="${y+43}">${esc(short(sub,Math.floor(w/(matchMedia('(max-width:800px)').matches?7:6))))}</text></g>`;}
function draw(){const e=entry,summary=entries.find(x=>x.id===currentId),gs=groups();let nodes='',edges='';const active=matched?'active':'';const edge=(x1,y1,x2,y2)=>`<path class="${active}" d="M${x1} ${y1} V${(y1+y2)/2} H${x2} V${y2}"/>`;
nodes+=node('entry',175,15,250,currentId,summary?.kind||'Library entry',active,true);
if(e){nodes+=node('subject',305,112,275,e.subject.artifact?.name||e.subject.name,e.subject.artifact?'Subject artifact / SHA-256 keyed':'Subject of the claim',active,true);edges+=edge(425,71,442,112);nodes+=node('checker',20,112,240,e.check?'Input checker':'No runnable checker',['Accept','Reject','No checker'].includes(result.title)?result.title:'No input checked',result.title==='Accept'?'accept':['Reject','No checker'].includes(result.title)?'reject':'',true);edges+=edge(175,71,140,112);
const width=gs.length===1?360:175,start=gs.length===1?120:20;gs.forEach(([name,files],i)=>{const col=i%3,row=Math.floor(i/3),x=start+col*193,y=220+row*80;nodes+=node('group:'+i,x,y,width,name,files.length+' delivered file'+(files.length===1?'':'s'),active,true);edges+=edge(442,168,x+width/2,y);});const bottom=220+Math.ceil(gs.length/3)*80+20;nodes+=node('requirements',20,bottom,270,'Required libraries',e.requires.join(', ')||'None',active,true);nodes+=node('toolchain',310,bottom,270,'Toolchain',e.toolchain.replace('leanprover/',''),active,true);const anchor=gs.length?220+(Math.ceil(gs.length/3)-1)*80+56:168,anchorX=gs.length===1?300:20+Math.max(0,gs.length-1)%3*193+87.5;edges+=edge(anchorX,anchor,155,bottom)+edge(anchorX,anchor,445,bottom);if(miss)nodes+=node('demand',165,bottom+90,270,miss,'No match / logged as demand','dangling',true);$('#graph').innerHTML=`<svg viewBox="0 0 600 ${bottom+(miss?165:80)}" role="img" aria-label="Selected proof dependency graph"><title>Entry, checker, subject, closure groups, libraries and toolchain</title>${edges}${nodes}</svg>`;
$('#graph-text').innerHTML=`<ul><li>Entry: ${esc(e.id)}${matched?' (matched lookup)':''}<ul><li>Subject: ${esc(e.subject.name)}${e.subject.artifact?' / artifact '+esc(e.subject.artifact.name):''}</li><li>Checker: ${e.check?'available':'not available'} / ${esc(result.title)}</li><li>Delivered closure: ${e.closure.length} files<ul>${gs.map(([dir,files])=>`<li><details><summary>${esc(dir)} / ${files.length} file${files.length===1?'':'s'}</summary><ul>${files.map(f=>`<li>${esc(f.path)}</li>`).join('')}</ul></details></li>`).join('')}</ul></li><li>Required libraries: ${e.requires.map(esc).join(', ')||'None'}</li><li>Toolchain: ${esc(e.toolchain)}</li></ul></li>${miss?`<li>Dangling demand: ${esc(miss)}. No matching proof.</li>`:''}</ul>`;
}else{$('#graph').innerHTML=`<svg viewBox="0 0 600 400" role="img" aria-label="Entry evidence unavailable">${nodes}${node('unavailable',130,140,340,'Recorded / not re-run','Full manifest unavailable in this mock')}${miss?node('demand',130,260,340,miss,'No match / logged as demand','dangling'):''}</svg>`;$('#graph-text').textContent=currentId+': recorded stub, not re-run by fvapi. Full manifest unavailable.';}
if(matchMedia('(max-width:800px)').matches)$('#graph').innerHTML=mobileGraph(e,summary,gs,active);$('#node-detail').innerHTML='';document.querySelectorAll('[data-node]').forEach(n=>{const activate=()=>inspect(n.dataset.node);n.onclick=activate;n.onkeydown=event=>{if(['Enter',' '].includes(event.key)){event.preventDefault();activate();}};});}
function mobileGraph(e,summary,gs,active){let nodes=node('entry',20,15,320,currentId,summary?.kind||'Library entry',active,true),edges='';const rail=(from,to,x=8)=>`<path class="${active}" d="M180 ${from} V${from+14} H${x} V${to+28} H20"/>`;if(e){nodes+=node('checker',20,105,320,e.check?'Input checker':'No runnable checker',['Accept','Reject','No checker'].includes(result.title)?result.title:'No input checked',result.title==='Accept'?'accept':['Reject','No checker'].includes(result.title)?'reject':'',true);nodes+=node('subject',20,195,320,e.subject.artifact?.name||e.subject.name,e.subject.artifact?'Subject artifact / SHA-256 keyed':'Subject of the claim',active,true);edges+=rail(71,105)+rail(71,195);gs.forEach(([dir,files],i)=>{const y=285+i*90;nodes+=node('group:'+i,20,y,320,dir,files.length+' delivered file'+(files.length===1?'':'s'),active,true);edges+=rail(251,y);});const bottom=285+gs.length*90;nodes+=node('requirements',20,bottom,320,'Required libraries',e.requires.join(', ')||'None',active,true)+node('toolchain',20,bottom+90,320,'Toolchain',e.toolchain.replace('leanprover/',''),active,true);gs.forEach((_,i)=>{edges+=`<path class="${active}" d="M340 ${313+i*90} H352 V${bottom-15} H180"/>`;});edges+=rail(bottom-15,bottom)+rail(bottom-15,bottom+90);if(miss)nodes+=node('demand',20,bottom+190,320,miss,'No match / logged as demand','dangling',true);return `<svg viewBox="0 0 360 ${bottom+(miss?270:170)}" role="img" aria-label="Selected proof dependency graph"><title>Entry, checker, subject, closure groups, libraries and toolchain</title>${edges}${nodes}</svg>`;}nodes+=node('unavailable',20,130,320,'Recorded / not re-run','Full manifest unavailable in this mock');return `<svg viewBox="0 0 360 220" role="img" aria-label="Entry evidence unavailable">${nodes}</svg>`;}
matchMedia('(max-width:800px)').addEventListener('change',draw);
function inspect(id){if(id==='checker'){$('#input').focus();return;}if(id==='demand'){logs('demand').catch(fail);return;}if(id.startsWith('group:')){const [dir,files]=groups()[+id.split(':')[1]];$('#node-detail').innerHTML=`<h3>${esc(dir)} / ${files.length} file${files.length===1?'':'s'}</h3><ul>${files.map(f=>`<li>${esc(f.path)} / ${f.bytes} bytes</li>`).join('')}</ul><button id="show-hashes">Inspect all hashes</button>`;$('#show-hashes').onclick=()=>{$('#package').open=true;$('#package').scrollIntoView({block:'start'});};return;}$('#package').open=true;$('#package').scrollIntoView({block:'start'});}
function remember(kind,query=null){sessionRecords.unshift({at:new Date().toISOString(),kind,entry_id:currentId,query,verdict:result.title,snapshot:{id:currentId,input:$('#input').value,matched,miss,result:{...result}}});}
async function lookup(){const value=$('#query').value.trim();if(!value)return;const r=await api('lookup',{spec_id:value});if(r.ok){await select(r.data.entry_id||r.data.entry?.id||r.data.id||value);matched=true;setResult('Found','The highlighted path connects the match to its proof package.',`Lookup / HTTP ${r.status}`);}else{matched=false;miss=value;setResult(r.status===404?'No match':'Lookup error',r.status===404?'Logged as demand. Try another specification.':r.data.detail,`Lookup / HTTP ${r.status}`);}draw();remember(r.ok?'lookup':'miss',{spec_id:value});await logs(r.ok?'answers':'demand');}
async function check(){let input;try{input=JSON.parse($('#input').value);}catch{setResult('Input error','The input is not valid JSON. Correct it and run the check again.');draw();return;}const r=await api('checks/'+encodeURIComponent(currentId),input);if(r.ok){setResult(r.data.verdict==='accept'?'Accept':'Reject',r.data.output?.reason||'Inspect the checker output and re-check locally.',`${r.data.elapsed_ms} ms / ${r.data.ran_on} / exit ${r.data.exit_code}`);if(r.data.recheck)$('#input-note').textContent='Re-check locally: '+r.data.recheck.command;}else{setResult(r.status===409?'No checker':'Check error',r.status===409?'This entry has no runnable checker. Select a checker entry.':r.data.detail,`Check / HTTP ${r.status}`);}draw();remember('check');await logs('answers');}
async function restore(record){if(record.snapshot){const s=record.snapshot;await select(s.id);$('#input').value=s.input;matched=s.matched;miss=s.miss;result={...s.result};result.metrics+=' / restored from this session';}else if(record.query){matched=false;miss=JSON.stringify(record.query);setResult('No match','Logged as demand. No matching proof was returned.','Restored from the demand log.');}else{await select(record.entry_id);matched=record.kind==='lookup';setResult(record.verdict?record.verdict[0].toUpperCase()+record.verdict.slice(1):'Found',record.kind==='check'?'Recorded verdict. The server log does not retain the input.':'Recorded lookup. The highlighted path shows the matched entry.','Restored from the answer log; no new request submitted.');if(record.kind==='check'){$('#input').value='';$('#input-note').textContent='Input unavailable in the server log. Load an example to start a new check.';}}
renderResult();draw();$('#readout').scrollIntoView({block:'nearest'});}
async function logs(next=mode){mode=next;$('#answers').setAttribute('aria-pressed',mode==='answers');$('#demand').setAttribute('aria-pressed',mode==='demand');const r=await api(mode);if(!r.ok)throw new Error(r.data.detail);const local=sessionRecords.filter(x=>mode==='demand'?x.kind==='miss':x.kind!=='miss');records=[...local,...(mode==='demand'?r.data.misses:r.data.answers)||[]];$('#log').innerHTML=(mode==='demand'?`<div class="counts">${(r.data.by_key||[]).map(x=>`<span>${esc(x.key)}: <strong>${x.count}</strong></span>`).join('')}</div>`:'')+(records.length?records.map((x,i)=>`<button class="log-row" data-record="${i}" aria-label="Restore ${esc(x.kind||'demand')} ${esc(x.entry_id||JSON.stringify(x.query))}"><span>${esc(x.snapshot?'This session':x.answer_id||x.miss_id||'Record')}</span><span>${esc(x.kind||'demand')} / ${esc(x.verdict|| (x.query?'no match':'found'))}</span><span>${esc(x.query?JSON.stringify(x.query):x.entry_id)}</span><span class="mark">Restore</span></button>`).join(''):'<p class="log-hint">No records yet. Look up a specification or run a check.</p>');document.querySelectorAll('[data-record]').forEach(b=>b.onclick=()=>restore(records[+b.dataset.record]).catch(fail));}
$('#lookup-form').onsubmit=event=>{event.preventDefault();lookup().catch(fail);};$('#run').onclick=()=>check().catch(fail);$('#example').onclick=()=>{if(entry?.check){$('#input').value=JSON.stringify(entry.check.example_input,null,2);$('#input-note').textContent='Example loaded. Edit the input or run the check.';}else setResult('No checker','Select a checker entry to load its example.');};$('#answers').onclick=()=>logs('answers').catch(fail);$('#demand').onclick=()=>logs('demand').catch(fail);
(async()=>{const catalog=await api('catalog');if(!catalog.ok)throw new Error(catalog.data.detail);entries=catalog.data.entries;$('#count').textContent=entries.length+' entries';$('#catalog').innerHTML=entries.map(e=>`<button class="selector" data-id="${esc(e.id)}" aria-pressed="false"><b>${esc(e.id)}</b><small>${esc(e.kind)} / ${esc(e.replay_status)}</small></button>`).join('');document.querySelectorAll('.selector').forEach(b=>b.onclick=()=>select(b.dataset.id).catch(fail));const full=await Promise.all(entries.map(e=>getEntry(e.id)));const checker=full.find(e=>e?.check),recorded=full.find(e=>e?.replay.status==='recorded')||entries.find(e=>e.replay_status==='recorded');const state=new URLSearchParams(location.search).get('state')||location.hash.slice(1)||'catalog';await select(['recorded','check-409'].includes(state)?recorded?.id||entries[0].id:checker?.id||entries[0].id);$('#query').value=checker?.id||'';await logs();if(['lookup-hit','lookup-miss'].includes(state)){$('#query').value=state==='lookup-hit'?checker.id:'unmatched.example';await lookup();}if(['check-accept','check-reject','check-409'].includes(state)){if(state==='check-reject'){const input=JSON.parse($('#input').value);input.rows[1].weights[0]+=1;$('#input').value=JSON.stringify(input,null,2);}await check();}if(state==='demand')await logs('demand');if(['entry','recorded'].includes(state))$('#package').open=true;document.body.dataset.ready='true';})().catch(fail);
